package Compress::Raw::Lzma::AloneDecoder;
use strict;
use warnings;
use File::Temp qw(tempfile);
sub new {
  my ($class, %opts) = @_;
  return bless { append => $opts{AppendOutput} ? 1 : 0 }, $class;
}
sub code {
  my ($self, $input, $output_ref) = @_;
  my ($fh, $path) = tempfile('task-lzma-XXXXXX', TMPDIR => 1, UNLINK => 1);
  binmode $fh;
  print {$fh} $input or return 'write failed';
  close $fh or return 'write failed';
  open my $pipe, '-|', 'xz', '--format=lzma', '--decompress', '--stdout', $path or return 'decoder launch failed';
  binmode $pipe;
  local $/;
  my $decoded = <$pipe>;
  my $ok = close $pipe;
  return 'Data is corrupt' unless $ok && defined $decoded;
  if ($self->{append}) { $$output_ref .= $decoded; }
  else { $$output_ref = $decoded; }
  return Compress::Raw::Lzma::LZMA_STREAM_END();
}
1;
EOF
perl -I/tmp/task-7z-perl -MCompress::Raw::Lzma -e 'my $d=Compress::Raw::Lzma::AloneDecoder->new(AppendOutput=>1); exit(!defined $d)'

