set -e
cd /app
key=$(perl -MDigest::SHA -MEncode -e '
  open my $f, q{<}, q{/app/solution.txt} or die;
  binmode $f; my $word = do { local $/; <$f> };
  die unless defined($word) && $word =~ /\A([^\n]+)\n\z/;
  my $pw = Encode::encode(q{UTF-16LE}, $1);
  my $s = Digest::SHA->new(256);
  for (my $i = 0; $i < (1 << 19); ++$i) { $s->add($pw); $s->add(pack(q{Q<}, $i)); }
  print $s->hexdigest;
')
test "${#key}" -eq 64
dd if=/app/secrets.7z bs=1 skip=32 count=144 status=none | openssl enc -aes-256-cbc -d -nopad -K "$key" -iv 7f2aeca3d70f5f1298c191ab0faf61fc | perl -e '
  binmode STDIN;
  my $plain = do { local $/; <STDIN> };
  open my $f, q{<}, q{/app/solution.txt} or die;
  binmode $f; my $word = do { local $/; <$f> }; chomp $word;
  die unless defined $plain && substr($plain, 0, 3) eq "\x01\x00\x08";
  die unless length($word) == ord(substr($plain, 2, 1));
  die unless substr($plain, 3, length($word)) eq $word;
  die unless substr($plain, 3 + length($word), 4) eq "\0\0\0\0";
'

