')
test "${#key}" -eq 64
dd if=/app/secrets.7z bs=1 skip=32 count=144 status=none | openssl enc -aes-256-cbc -d -nopad -K "$key" -iv 7f2aeca3d70f5f1298c191ab0faf61fc | perl -e '
  binmode STDIN;
  my $plain = do { local $/; <STDIN> };
  open my $f, q{<}, q{/app/solution.txt} or die q{solution unavailable};
  binmode $f;
  my $saved = do { local $/; <$f> };
  die q{bad solution framing} unless defined($saved) && $saved =~ /\A([^\r\n]+)\n\z/;
  my $word = $1;
  die q{bad plaintext frame} unless defined($plain) && substr($plain, 0, 3) eq "\x01\x00\x08";
  die q{length mismatch} unless length($word) == ord(substr($plain, 2, 1));
  die q{word mismatch} unless substr($plain, 3, length($word)) eq $word;
  die q{frame terminator mismatch} unless substr($plain, 3 + length($word), 4) eq "\0\0\0\0";
'

